import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.stream.Collectors;

public class Solution {
    static final long MOD = 998244353L;

    public static void main(String[] args) throws IOException {
        String all = new BufferedReader(new InputStreamReader(System.in))
                .lines()
                .collect(Collectors.joining(" "));
        String[] tokens = all.trim().split("\\s+");
        int idx = 0;
        long n = Long.parseLong(tokens[idx++]);
        long m = Long.parseLong(tokens[idx++]);
        long l = Long.parseLong(tokens[idx++]);
        long r = Long.parseLong(tokens[idx++]);

        PrintWriter out = new PrintWriter(System.out);
        long area = n * m;

        if ((area & 1) == 1) {
            out.println(binpow(r - l + 1, area));
            out.close();
            return;
        }

        long evenCount = r / 2 - (l - 1) / 2;
        long oddCount = r - l + 1 - evenCount;

        long answer = (binpow(evenCount + oddCount, area) + binpow(evenCount - oddCount, area)) % MOD;
        answer = (answer * binpow(2, MOD - 2)) % MOD;

        out.println(answer);
        out.close();
    }

    static long binpow(long base, long power) {
        long result = 1L;
        while (power > 0) {
            if ((power & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            power >>= 1;
        }
        return result;
    }
}
